```bash
set -e;
repo_name=AutoNTT;
out_dir=/output/$repo_name;
mkdir -p "$out_dir";
designs=($(find /workspace/repo/examples -mindepth 2 -maxdepth 2 -type d));
for d in "${designs[@]}"; do
  design_name=$(basename "$d");
  design_dir="$out_dir/$design_name";
  mkdir -p "$design_dir";
  cp -r "$d"/* "$design_dir"/;
  # create README
  echo "# Design $design_name" > "$design_dir/README.md";
  echo "Source files:" >> "$design_dir/README.md";
  find "$design_dir" -type f -printf " - %P\n" >> "$design_dir/README.md";
  # compile each .cpp
  mkdir -p "$design_dir/logs";
  for src in $(find "$design_dir" -name '*.cpp'); do
    clang++ -std=c++17 -I/workspace/stubs -I"$design_dir" -w -fsyntax-only "$src" > "$design_dir/logs/$(basename "$src".log)" 2>&1 || true;
  done
  # generate synth.tcl placeholder
  echo "open_project $design_name" > "$design_dir/synth.tcl";
  echo "set_top top_function" >> "$design_dir/synth.tcl";
  echo "add_files *.cpp" >> "$design_dir/synth.tcl";
  echo "add_files -tb *_test.cpp" >> "$design_dir/synth.tcl";
  echo "open_solution \"solution1\"" >> "$design_dir/synth.tcl";
  echo "set_part xcu250-figd2104-2L-e" >> "$design_dir/synth.tcl";
  echo "csynth_design" >> "$design_dir/synth.tcl";
  echo "exit" >> "$design_dir/synth.tcl";
done;
# create manifest
manifest="$out_dir/manifest.json";
echo "{" > "$manifest";
echo "  \"repo_name\": \"$repo_name\"," >> "$manifest";
echo "  \"repo_url\": \"https://github.com/SFU-HiAccel/AutoNTT.git\"," >> "$manifest";
echo "  \"framework\": \"unknown\"," >> "$manifest";
echo "  \"total_designs\": $(ls -1 $out_dir | wc -l)," >> "$manifest";
echo "  \"designs\": []" >> "$manifest";
echo "}" >> "$manifest";
```

